public class MainView extends VerticalLayout {
    private TextField itemField;
    private Button addButton;
    private Button clearButton;
    private UnorderedList itemList;
    private Span itemCount;

    public MainView() {
        setPadding(true);
        setSpacing(true);

        H1 heading = new H1("Items");
        add(heading);

        itemField = new TextField("Item");
        itemField.setWidth("300px");
        add(itemField);

        HorizontalLayout buttonLayout = new HorizontalLayout();
        buttonLayout.setSpacing(true);

        addButton = new Button("Add", event -> handleAddItem());
        clearButton = new Button("Clear", event -> handleClearItems());

        buttonLayout.add(addButton, clearButton);
        add(buttonLayout);

        itemList = new UnorderedList();
        add(itemList);

        itemCount = new Span("Items: 0");
        add(itemCount);

        updateCount();
    }

    private void handleAddItem() {
        String value = itemField.getValue().trim();

        if (value.isEmpty()) {
            itemField.setInvalid(true);
            return;
        }

        itemField.setInvalid(false);

        ListItem item = new ListItem(value);
        itemList.add(item);

        itemField.clear();
        updateCount();
    }

    private void handleClearItems() {
        itemList.removeAllChildren();
        itemField.setInvalid(false);
        updateCount();
    }

    private void updateCount() {
        int count = itemList.getChildren().count();
        itemCount.setText("Items: " + count);
    }
